mapper.select:
SELECT banner_id, image, link_url, sort_order, status, create_by, create_time, update_by, update_time
FROM zhw_home_banner
WHERE banner_id = #{bannerId}

mapper.update:
UPDATE zhw_home_banner
image = #{image}, link_url = #{linkUrl}, sort_order = #{sortOrder}, status = #{status}, update_by = #{updateBy}, update_time = NOW()
WHERE banner_id = #{bannerId}
